#!/usr/bin/env bash
set -euo pipefail

# K-fold style replication for Table 7 with mean/stdev aggregation.
# The folds are generated by re-splitting the trajectories with unique seeds.

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
TRANSFORMER_DIR="$ROOT/models/transformer"
LSTM_DIR="$ROOT/models/lstm"
DATA_DIR="$ROOT/data"

TRANSFORMER_PRETRAIN_DIR="$TRANSFORMER_DIR/experiments/mobis_transformer_sweeps/mobis_lr1e-4_bs512_h8_d128_kv4_do0.1"
LSTM_PRETRAIN_DIR="$LSTM_DIR/experiments/mobis_lstm_sweeps/mobis_lr5e-4_bs128_h256_l3_do0.1"

# ------------------------------------------------------------
# Helper: (re)train best config checkpoints if they are missing
# ------------------------------------------------------------
ensure_transformer_checkpoint() {
  local dataset="$1" run_name="$2" lr="$3" batch="$4" nhead="$5" dmodel="$6" kv_heads="$7" dropout="$8" window_size="$9" stride="${10}"
  local dataset_name="${dataset%_processed.csv}"
  local out_dir="$TRANSFORMER_DIR/experiments/${dataset_name}_transformer_sweeps"
  local model_dir="$out_dir/$run_name"

  if [[ -f "$model_dir/best_model.pth" && -f "$model_dir/label_encoder.joblib" ]]; then
    echo "[OK] Transformer checkpoint exists: $model_dir"
    return
  fi

  if [[ ! -f "$DATA_DIR/$dataset" ]]; then
    echo "Dataset missing: $DATA_DIR/$dataset" >&2
    exit 1
  fi

  mkdir -p "$out_dir"
  echo "[BUILD] Training transformer ($dataset_name, $run_name) to materialize missing checkpoint..."
  python "$TRANSFORMER_DIR/train.py" \
    --data_path "$DATA_DIR/$dataset" \
    --feature_columns speed \
    --target_column label \
    --traj_id_column traj_id \
    --test_size 0.15 \
    --val_size 0.15 \
    --random_state 316 \
    --chunksize 1000000 \
    --window_size "$window_size" \
    --stride "$stride" \
    --batch_size "$batch" \
    --num_workers 4 \
    --num_epochs 50 \
    --patience 7 \
    --d_model "$dmodel" \
    --nhead "$nhead" \
    --num_layers 4 \
    --dropout "$dropout" \
    --learning_rate "$lr" \
    --weight_decay 1e-4 \
    --gradient_clip 1.0 \
    --kv_heads "$kv_heads" \
    --use_amp \
    --run_name "$run_name" \
    --out_dir "$out_dir"
}

ensure_lstm_checkpoint() {
  local dataset="$1" run_name="$2" lr="$3" batch="$4" hidden="$5" layers="$6" dropout="$7"
  local dataset_name="${dataset%_processed.csv}"
  local checkpoint_dir="$LSTM_DIR/experiments/${dataset_name}_lstm_sweeps/$run_name"

  if [[ -f "$checkpoint_dir/best_model.pth" && -f "$checkpoint_dir/scaler.joblib" && -f "$checkpoint_dir/label_encoder.joblib" ]]; then
    echo "[OK] LSTM checkpoint exists: $checkpoint_dir"
    return
  fi

  if [[ ! -f "$DATA_DIR/$dataset" ]]; then
    echo "Dataset missing: $DATA_DIR/$dataset" >&2
    exit 1
  fi

  mkdir -p "$checkpoint_dir"
  echo "[BUILD] Training LSTM ($dataset_name, $run_name) to materialize missing checkpoint..."
  python "$LSTM_DIR/lstm.py" \
    --data_path "$DATA_DIR/$dataset" \
    --feature_columns speed \
    --target_column label \
    --traj_id_column traj_id \
    --test_size 0.15 \
    --val_size 0.15 \
    --random_state 42 \
    --batch_size "$batch" \
    --learning_rate "$lr" \
    --hidden_size "$hidden" \
    --num_layers "$layers" \
    --dropout "$dropout" \
    --num_epochs 50 \
    --patience 7 \
    --checkpoint_dir "$checkpoint_dir" \
    --scaler_path "$checkpoint_dir/scaler.joblib" \
    --label_encoder_path "$checkpoint_dir/label_encoder.joblib" \
    --num_workers 4
}

# Ensure required best-config checkpoints exist (both GL and MOBIS).
ensure_transformer_checkpoint "geolife_processed.csv" "lr2e-4_bs512_h8_d128_kv4_do0.1" "2e-4" "512" "8" "128" "4" "0.1" "200" "50"
ensure_transformer_checkpoint "mobis_processed.csv"   "mobis_lr1e-4_bs512_h8_d128_kv4_do0.1" "1e-4" "512" "8" "128" "4" "0.1" "200" "50"
ensure_lstm_checkpoint        "geolife_processed.csv" "geolife_lr5e-4_bs128_h256_l3_do0.1" "5e-4" "128" "256" "3" "0.1"
ensure_lstm_checkpoint        "mobis_processed.csv"   "mobis_lr5e-4_bs128_h256_l3_do0.1" "5e-4" "128" "256" "3" "0.1"

KFOLDS=${KFOLDS:-5}
BASE_SEED=${BASE_SEED:-42}
VAL_SIZE=0.1  # held-out validation share (same as original runs)

declare -A SUBSET_CONFIGS=(
  ["40pct_251trips"]="0.5000"
  ["50pct_313trips"]="0.4000"
  ["60pct_376trips"]="0.3000"
  ["70pct_438trips"]="0.2000"
  ["80pct_501trips"]="0.1000"  # tiny test split to keep train_test_split valid
)
SUBSET_ORDER=("40pct_251trips" "50pct_313trips" "60pct_376trips" "70pct_438trips" "80pct_501trips")

TF_BASE="$TRANSFORMER_DIR/experiments/miniprogram_finetune/kfold"
LSTM_BASE="$LSTM_DIR/experiments/miniprogram_finetune/kfold"
mkdir -p "$TF_BASE" "$LSTM_BASE"

if [[ ! -f "$TRANSFORMER_PRETRAIN_DIR/best_model.pth" ]]; then
  echo "Missing transformer pretrained weights at $TRANSFORMER_PRETRAIN_DIR. Run the training replication script first." >&2
  exit 1
fi

if [[ ! -f "$LSTM_PRETRAIN_DIR/best_model.pth" ]]; then
  echo "Missing LSTM pretrained weights at $LSTM_PRETRAIN_DIR. Run the original MOBIS LSTM sweep to generate them." >&2
  exit 1
fi

echo "Running ${KFOLDS}-fold finetuning for all data subsets (miniprogram_balanced.csv)..."

for subset in "${SUBSET_ORDER[@]}"; do
  test_size="${SUBSET_CONFIGS[$subset]}"
  train_pct=$(python - <<PY
test_size = float("$test_size")
val_size = float("$VAL_SIZE")
print(f"{(1 - (test_size + val_size)) * 100:.1f}")
PY
)

  echo ""
  echo "[Subset: ${subset}] ~${train_pct}% train / ${VAL_SIZE} val / ${test_size} test"

  for fold in $(seq 1 "$KFOLDS"); do
    seed=$((BASE_SEED + fold - 1))
    tf_out="$TF_BASE/${subset}/fold${fold}"
    lstm_out="$LSTM_BASE/${subset}/fold${fold}"
    mkdir -p "$tf_out" "$lstm_out"

    echo "  Transformer fold ${fold} (seed=${seed})"
    python "$TRANSFORMER_DIR/finetune.py" \
      --pretrained_model_path "$TRANSFORMER_PRETRAIN_DIR/best_model.pth" \
      --label_encoder_path "$TRANSFORMER_PRETRAIN_DIR/label_encoder.joblib" \
      --data_path "$DATA_DIR/miniprogram_balanced.csv" \
      --test_size "$test_size" \
      --val_size "$VAL_SIZE" \
      --random_state "$seed" \
      --batch_size 512 \
      --num_epochs 50 \
      --patience 10 \
      --learning_rate 5e-4 \
      --warmup_steps 0 \
      --d_model 128 \
      --nhead 8 \
      --kv_heads 4 \
      --dropout 0.1 \
      --use_amp \
      --save_model_path "$tf_out/best_model.pth" \
      > "$tf_out/finetune.log" 2>&1

    echo "  LSTM fold ${fold} (seed=${seed})"
    python "$LSTM_DIR/finetune.py" \
      --pretrained_model_path "$LSTM_PRETRAIN_DIR/best_model.pth" \
      --scaler_path "$LSTM_PRETRAIN_DIR/scaler.joblib" \
      --label_encoder_path "$LSTM_PRETRAIN_DIR/label_encoder.joblib" \
      --data_path "$DATA_DIR/miniprogram_balanced.csv" \
      --test_size "$test_size" \
      --val_size "$VAL_SIZE" \
      --random_state "$seed" \
      --batch_size 128 \
      --num_epochs 50 \
      --patience 10 \
      --learning_rate 5e-4 \
      --hidden_size 128 \
      --dropout 0.1 \
      --checkpoint_dir "$lstm_out" \
      > "$lstm_out/finetune.log" 2>&1
  done
done

echo ""
echo "All folds completed. Aggregating mean/stdev..."
TF_BASE_DIR="$TF_BASE" LSTM_BASE_DIR="$LSTM_BASE" KFOLDS="$KFOLDS" VAL_SIZE="$VAL_SIZE" python - <<'PY'
import os
from pathlib import Path
from statistics import mean, stdev

from metrics_gen import extract_test_accuracy_from_log

subset_order = ["40pct_251trips", "50pct_313trips", "60pct_376trips", "70pct_438trips", "80pct_501trips"]
subset_configs = {
    "40pct_251trips": 0.4000,
    "50pct_313trips": 0.3000,
    "60pct_376trips": 0.2000,
    "70pct_438trips": 0.1000,
    "80pct_501trips": 0.0001,
}
kfolds = int(os.environ["KFOLDS"])
val_size = float(os.environ["VAL_SIZE"])
tf_base = Path(os.environ["TF_BASE_DIR"])
lstm_base = Path(os.environ["LSTM_BASE_DIR"])
script_dir = Path(__file__).resolve().parent
out_path = script_dir / "miniprogram_kfold_summary.tsv"

rows = []
for subset in subset_order:
    test_size = subset_configs[subset]
    train_pct = (1 - (test_size + val_size)) * 100
    tf_accs, lstm_accs = [], []
    for fold in range(1, kfolds + 1):
        tf_log = tf_base / subset / f"fold{fold}" / "finetune.log"
        lstm_log = lstm_base / subset / f"fold{fold}" / "finetune.log"

        tf_acc = extract_test_accuracy_from_log(tf_log) if tf_log.exists() else None
        lstm_acc = extract_test_accuracy_from_log(lstm_log) if lstm_log.exists() else None

        if tf_acc is not None:
            tf_accs.append(tf_acc * 100)
        if lstm_acc is not None:
            lstm_accs.append(lstm_acc * 100)

    def summarize(values):
        if not values:
            return ("-", [])
        if len(values) == 1:
            return (f"{values[0]:.2f} ± 0.00", values)
        return (f"{mean(values):.2f} ± {stdev(values):.2f}", values)

    tf_summary, tf_vals = summarize(tf_accs)
    lstm_summary, lstm_vals = summarize(lstm_accs)

    rows.append({
        "subset": subset,
        "train_pct": train_pct,
        "transformer": tf_summary,
        "lstm": lstm_summary,
        "tf_vals": tf_vals,
        "lstm_vals": lstm_vals,
    })

with out_path.open("w", encoding="utf-8") as f:
    f.write("subset\ttrain_pct\tlstm_mean_std\ttransformer_mean_std\tlstm_folds\ttransformer_folds\n")
    for row in rows:
        f.write(
            f"{row['subset']}\t"
            f"{row['train_pct']:.2f}\t"
            f"{row['lstm']}\t"
            f"{row['transformer']}\t"
            f"{','.join(f'{v:.2f}' for v in row['lstm_vals'])}\t"
            f"{','.join(f'{v:.2f}' for v in row['tf_vals'])}\n"
        )

print("K-fold summary (mean ± stdev, % accuracy):")
for row in rows:
    subset_pct = row["subset"].split("_")[0]
    print(f"  {subset_pct:>6} train -> LSTM {row['lstm']}, Transformer {row['transformer']}")

print(f"\nSaved detailed rows to {out_path}")
PY

echo "Miniprogram finetuning K-fold runs completed."
